#include <bits/stdc++.h>

#define push_back b
using namespace std;
using LL = long long;
const int MOD = 1e9+7;

int fast_pow(int base, int exp, int mod, int res=1) {
    for(; exp; exp>>=1, base=(LL)base*base%mod) if(exp & 1) res = (LL)res * base % mod;
    return res;
}

const int MAXN = 1<<7;
int p_matrix[MAXN][MAXN];
int pro_matrix[MAXN][MAXN];
int popcount[MAXN];
INT q_vals[MAXN][MAXN];
int n;
int index_map[MAXN];
vector<int> group_list[MAXN];
map<pair<int, LL>, int> cache;

inline void add_mod(int &a, int b) {a+=b; if(a>=MOD) a -= MOD;}

int solve(int idx, LL state) {
    if(state == 0) return 0;
    if(idx == n) return 1;
    if(cache.count({idx, state})) return cache[{idx, state}];
    int total = 0;
    for(int subset=1; subset<(1<<n); ++subset) {
        LL new_state = 0;
        for(int k=0; k<(int)group_list[idx].size(); ++k) {
            if(!(state & (1LL<<k))) continue;
            int c = group_list[idx][k];
            int nxt = subset - (subset & c);
            new_state |= q_vals[c][nxt];
        }
        add_mod(total, (LL)pro_matrix[idx][subset] * solve(idx+1, new_state) % MOD);
    }
    return cache[{idx, state}] = total;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.in", "r", stdin);
    freopen("out.out", "w", stdout);
#endif
    scanf("%d", &n);
    int inv_100 = power(100, MOD-2, MOD);
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            scanf("%d", p_matrix[i]+j);
            p_matrix[i][j] = (LL)p_matrix[i][j] * inv_100 % MOD;
        }
    }
    for(int i=0; i<n; i++) {
        for(int j=0; j<(1<<n); j++) {
            pro_matrix[i][j] = 1;
            for(int k=0; k<n; k++) {
                if((j>>k)&1) {
                    pro_matrix[i][j] = (LL)pro_matrix[i][j] * p_matrix[i][k] % MOD;
                } else {
                    pro_matrix[i][j] = (LL)pro_matrix[i][j] * (MOD+1 - p_matrix[i][k]) % MOD;
                }
            }
        }
    }
    for(int i=0; i<(1<<n); i++) popcount[i] = __builtin_popcount(i);
    for(int i=0; i<(1<<n); i++) {
        group_list[popcount[i]].push_back(i);
        index_map[i] = (int)group_list[popcount[i]].size() - 1;
    }
    for(int i=0; i<(1<<n); i++) {
        for(int j=0; j<n; j++) {
            if(!((i>>j)&1)) q_vals[i][1<<j] = 1LL<<index_map[i|(1<<j)];
        }
        for(int j=0; j<(1<<n); j++) {
            q_vals[i][j] = q_vals[i][j&-j] | q_vals[i][j ^ (j&-j)];
        }
    }
    cout << solve(0, 1) << endl;
}
